#!/usr/bin/python

"""
This script sets up proxy manager server for common UE project.

Proxy manager performs releases search/upload/removal and can start UE-proxy based on specified release.
"""
import json
import os
import sys


def run():
    current_dir = os.path.abspath(os.curdir)
    if current_dir not in sys.path:
        sys.path.insert(0, current_dir)

    from . import cmd_line
    from ._vendor.ue_proxy import logger as proxy_logger
    from ._vendor.ue_proxy.runners import uvicorn_runner

    os.system("")

    cli_options = vars(cmd_line.parse_mngr_options())
    # need to pass jsoned via env since uvicorn will run new process
    os.environ['MNGR_CMD_LINE_OPTIONS'] = json.dumps(cli_options)

    if os.environ.get('PYTHONASYNCIODEBUG', None):
        proxy_logger.configure_debugging()

    keyfile = cli_options['ssl_keyfile']
    certfile = cli_options['ssl_certfile']
    if certfile:
        print(f"Starting HTTPS server - using certificate from {certfile}")  # noqa: T201
    else:
        print("No certificate provided - starting HTTP server")  # noqa: T201
    try:
        uvicorn_runner.run("taf.ue.proxy.mngr.uservice.upgrade:app", allow_restarts=True,
                           host="", port=int(cli_options['port']),
                           ssl_keyfile=keyfile, ssl_certfile=certfile,
                           log_level="info")
    except KeyboardInterrupt:
        ...


if __name__ == '__main__':
    run()
